<template>
  <div class="register-page">
    <canvas ref="bgCanvas" class="bg-canvas"></canvas>
    <div class="register-card">
      <div class="register-header">
        <div class="card-dot"></div>
        <div class="card-title">注册账号</div>
        <div class="card-sub">加入社团场地管理平台</div>
      </div>
      <el-form ref="form" :model="form" :rules="rules" @submit.native.prevent="submit">
        <el-form-item prop="username">
          <el-input v-model="form.username" size="small" placeholder="用户名" prefix-icon="el-icon-user" />
        </el-form-item>
        <el-form-item prop="password">
          <el-input v-model="form.password" size="small" type="password" placeholder="密码（至少6位）" prefix-icon="el-icon-lock" show-password />
        </el-form-item>
        <el-form-item prop="nickname">
          <el-input v-model="form.nickname" size="small" placeholder="昵称" prefix-icon="el-icon-edit-outline" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" size="small" class="register-btn" @click="submit" :loading="loading">注 册</el-button>
        </el-form-item>
        <div class="link-login">
          已有账号？<router-link to="/login">去登录</router-link>
        </div>
      </el-form>
    </div>
  </div>
</template>

<script>
import request from '@/api'

export default {
  name: 'Register',
  data() {
    return {
      form: { username: '', password: '', nickname: '' },
      rules: {
        username: [{ required: true, message: '请输入用户名', trigger: 'blur' }],
        password: [
          { required: true, message: '请输入密码', trigger: 'blur' },
          { min: 6, message: '密码至少6位', trigger: 'blur' }
        ],
        nickname: [{ required: true, message: '请输入昵称', trigger: 'blur' }]
      },
      loading: false
    }
  },
  mounted() { this.initCanvas(); window.addEventListener('resize', this.handleResize) },
  beforeDestroy() { if (this.animId) cancelAnimationFrame(this.animId); window.removeEventListener('resize', this.handleResize) },
  methods: {
    async submit() {
      try { await this.$refs.form.validate() } catch { return }
      this.loading = true
      try {
        const res = await request.post('/user/register', this.form)
        if (res.code === 200) {
          this.$message.success('注册成功，请登录')
          this.$router.push('/login')
        } else {
          this.$message.error(res.message || '注册失败')
        }
      } catch { this.$message.error('注册失败') }
      finally { this.loading = false }
    },
    initCanvas() {
      const canvas = this.$refs.bgCanvas; if (!canvas) return
      const ctx = canvas.getContext('2d'); let w, h
      const resize = () => {
        w = window.innerWidth; h = window.innerHeight
        const dpr = window.devicePixelRatio || 1
        canvas.width = w * dpr; canvas.height = h * dpr
        canvas.style.width = w + 'px'; canvas.style.height = h + 'px'
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      }; resize(); this.handleResize = resize
      const count = 60; const particles = []
      for (let i = 0; i < count; i++) {
        particles.push({
          x: Math.random() * w, y: Math.random() * h, r: Math.random() * 2 + 0.5,
          vx: (Math.random() - 0.5) * 0.3, vy: (Math.random() - 0.5) * 0.3, alpha: Math.random() * 0.35 + 0.1
        })
      }
      const draw = () => {
        ctx.clearRect(0, 0, w, h)
        ctx.strokeStyle = 'rgba(0,191,255,0.04)'; ctx.lineWidth = 1
        const gridSize = 50
        for (let x = 0; x <= w; x += gridSize) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke() }
        for (let y = 0; y <= h; y += gridSize) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke() }
        particles.forEach(p => {
          p.x += p.vx; p.y += p.vy
          if (p.x < 0) p.x = w; if (p.x > w) p.x = 0
          if (p.y < 0) p.y = h; if (p.y > h) p.y = 0
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
          ctx.fillStyle = `rgba(99,102,241,${p.alpha})`; ctx.fill()
          ctx.beginPath(); ctx.arc(p.x, p.y, p.r * 2.5, 0, Math.PI * 2)
          ctx.fillStyle = `rgba(0,191,255,${p.alpha * 0.3})`; ctx.fill()
        })
        this.animId = requestAnimationFrame(draw)
      }; draw()
    }
  }
}
</script>

