.register-card { position: relative; z-index: 1; width: 380px; background: rgba(255,255,255,0.06); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border: 1px solid rgba(255,255,255,0.08); border-radius: 12px; padding: 36px 32px 28px; box-shadow: 0 20px 60px rgba(0,0,0,0.4) }
.register-header { text-align: center; margin-bottom: 28px }
.card-dot { width: 10px; height: 10px; border-radius: 50%; background: linear-gradient(135deg, #00BFFF, #6366F1); margin: 0 auto 14px; box-shadow: 0 0 16px rgba(0,191,255,0.5) }
.card-title { font-size: 22px; font-weight: 700; color: #e2e8f0; letter-spacing: 1px; margin-bottom: 6px }
.card-sub { font-size: 12px; color: rgba(148,163,184,0.7); letter-spacing: 0.5px }
.register-card >>> .el-input__inner { background: rgba(255,255,255,0.06) !important; border: 1px solid rgba(255,255,255,0.1) !important; color: #e2e8f0 !important; border-radius: 6px; height: 40px }
.register-card >>> .el-input__inner::placeholder { color: rgba(148,163,184,0.5) !important }
.register-card >>> .el-input__inner:focus { border-color: #00BFFF !important; box-shadow: 0 0 0 2px rgba(0,191,255,0.15) !important }
